  {
    "target": [ "e1" ],
    "entities": [
      { "id": "e1", "type": "Movie" },
      { "id": "e2", "type": "Actor" }
    ],
    "relationships": [
      { "id": "r1", "role": "acted_in", "from": "e2", "to": "e1" }
    ],
    "constraint": {
      "list": {
        "nodes_of": "p1",
        "node_id": "e2"
      },
      "condition": {
        "and_conditions": [
          { "left": { "attribute_name": "role", "of": "e2" }, "operator": "=", "right": "lead" },
          {
            "left": { "attribute_name": "earnings", "of": "e2" },
            "operator": ">",
            "right": {
              "list": {
                "list": { "list_elements": "e4" },
                "filter": {
                  "and_conditions": [
                    { "left": { "attribute_name": "nationality", "of": "e4" }, "operator": "=", "right": "Argentina" }
                  ]
                },
                "map_expression": { "attribute_name": "earnings", "of": "e4" },
                "aggregate_kind": "MAX"
              }
            }
          }
        ]
      },
      "quantifier_kind": "ALL"
    },
    "paths": [
      { "id": "p1", "start": "e2", "end": "e1", "roles": ["acted_in"] }
    ]
  }
]
